using Xunit;

public class U26_MiscTests
{
    [Fact]
    public void Test_VIRTUA_1_1()
    {
        // Arrange
        string username = "validuser";
        string password = "validpassword";

        // Act
        bool loginResult = AuthenticationService.Login(username, password);

        // Assert
        Assert.True(loginResult);
    }

    [Fact]
    public void Test_VIRTUA_1_2()
    {
        // Arrange
        string username = "administrator";

        // Act
        string userId = UserService.GetUserId(username);

        // Assert
        Assert.NotNull(userId);
    }

    [Fact]
    public void Test_VCMMNU01()
    {
        // Arrange
        string[] menuOptions = { "Maintain Speciality", "Maintain Doctors", "Maintain Chemist & Labs", "Maintain Symptoms" };

        // Act
        string[] displayedOptions = VirtualClinicMenu.GetMenuOptions();

        // Assert
        Assert.Equal(menuOptions, displayedOptions);
    }

    [Fact]
    public void Test_VCMSYS01()
    {
        // Arrange
        string[] adminScreens = { "Set-up Users/ Passwords", "Set-up Control File", "Create Appointment File", "View/ Print Invoice", "Back-ups", "Archive Patient Profiles" };

        // Act
        string[] displayedScreens = AdministratorSystem.GetAdminScreens();

        // Assert
        Assert.Equal(adminScreens, displayedScreens);
    }

    [Fact]
    public void Test_VCSYSS02()
    {
        // Arrange
        string[] userTypes = { "Doctor(s)", "Chemists and Labs" };

        // Act
        string[] createdUsers = UserManagement.CreateUserTypes(userTypes);

        // Assert
        Assert.Equal(userTypes, createdUsers);
    }

    [Fact]
    public void Test_VCMSP01()
    {
        // Arrange
        string specialityId = "1";
        string specialityName = "Cardiology";
        string specialityDescription = "Treatment of heart conditions";

        // Act
        Speciality createdSpeciality = SpecialityService.AddSpeciality(specialityId, specialityName, specialityDescription);

        // Assert
        Assert.Equal(specialityId, createdSpeciality.Id);
        Assert.Equal(specialityName, createdSpeciality.Name);
        Assert.Equal(specialityDescription, createdSpeciality.Description);
    }

    [Fact]
    public void Test_VCMSP03_1()
    {
        // Arrange
        string specialityId = "1";
        string updatedSpecialityName = "Pediatrics";

        // Act
        Speciality updatedSpeciality = SpecialityService.UpdateSpeciality(specialityId, updatedSpecialityName);

        // Assert
        Assert.Equal(specialityId, updatedSpeciality.Id);
        Assert.Equal(updatedSpecialityName, updatedSpeciality.Name);
    }
}

